begin;
select plan(18);
select has_function('concierge','review_guidance_stage_ids_unique_v1',array['jsonb'],'one private exact stage identity predicate');
select is((select count(*)::integer from pg_proc p where p.oid='concierge.review_guidance_stage_ids_unique_v1(jsonb)'::regprocedure and (has_function_privilege('anon',p.oid,'execute') or has_function_privilege('authenticated',p.oid,'execute') or has_function_privilege('service_role',p.oid,'execute'))),0,'no app/service raw helper execute right');
select ok((select not prosecdef and proconfig @> array['search_path=""'] from pg_proc where oid='concierge.review_guidance_stage_ids_unique_v1(jsonb)'::regprocedure),'invoker helper has empty search path');
select ok(concierge.review_guidance_stage_ids_unique_v1('{"kind":"review"}'),'non-instruction predicate is unchanged');
select ok(concierge.review_guidance_stage_ids_unique_v1('{"kind":"instruction","schedule":{"stages":[]}}'),'empty stages allowed');
select ok(concierge.review_guidance_stage_ids_unique_v1('{"kind":"instruction","schedule":{"stages":[{"id":"first"},{"id":"second"}]}}'),'distinct opaque identities allowed');
select ok(concierge.review_guidance_stage_ids_unique_v1('{"kind":"instruction","schedule":{"stages":[{"id":"Case"},{"id":"case"}]}}'),'case preserved, no case folding');
select ok(not concierge.review_guidance_stage_ids_unique_v1('{"kind":"instruction","schedule":{"stages":[{"id":"same","directions":"one"},{"id":"same","directions":"two"}]}}'),'duplicate identities rejected despite different directions');
select ok(not concierge.review_guidance_stage_ids_unique_v1('{"kind":"instruction","schedule":{"stages":[{"id":"a"},{"id":"b"},{"id":"a"}]}}'),'non-adjacent duplicates rejected');
select ok(concierge.review_guidance_stage_ids_unique_v1('{"kind":"instruction","schedule":{"stages":[{"id":"first","directions":"same"},{"id":"second","directions":"same"}]}}'),'same directions do not define identity');
select is((select count(*)::integer from jsonb_object_keys(concierge.review_command_fields())),15,'Review15 unchanged');
select is((select count(*)::integer from jsonb_object_keys(concierge.guidance_command_fields())),9,'Guidance9 unchanged');
select is((select count(*)::integer from jsonb_object_keys(concierge.plan_command_fields())),26,'Plan26 unchanged');
select is((select count(*)::integer from jsonb_object_keys(concierge.care_command_fields())),13,'Care13 unchanged');
select ok((select prosrc like '%review_guidance_stage_ids_unique_v1(b)%' from pg_proc where oid='concierge.review_guidance_body_check(uuid,jsonb)'::regprocedure),'create/save use exact identity predicate');
select ok((select prosrc like '%review_guidance_stage_ids_unique_v1(b)%' from pg_proc where oid='concierge.review_guidance_issues(uuid,jsonb,jsonb,jsonb,boolean)'::regprocedure),'review/approve/final/deferred readiness uses same predicate');
select ok((select prosrc like '%review_guidance_stage_ids_unique_v1(r.body)%' from pg_proc where oid='concierge.review_guidance_draft_view(concierge.review_guidance_drafts)'::regprocedure),'old invalid drafts cannot return usable authority');
select ok((select prosrc like '%review_guidance_stage_ids_unique_v1(body)%' from pg_proc where oid='concierge.review_request_authorize(concierge.review_requests)'::regprocedure),'cached replay/status keeps current authorization and structural fence');
select * from finish();
rollback;
